import random

def quick_sort_3way(nums, lo, hi):
    if lo >= hi:
        return
    pivot = nums[random.randint(lo, hi)]
    lt, i, gt = lo - 1, lo, hi + 1   # <pivot 区 | 未定区 | >pivot 区
    while i < gt:
        if nums[i] < pivot:
            nums[lt + 1], nums[i] = nums[i], nums[lt + 1]
            lt += 1
            i += 1
        elif nums[i] > pivot:
            nums[gt - 1], nums[i] = nums[i], nums[gt - 1]
            gt -= 1                   # i 不动：换来的数未检查
        else:
            i += 1
    quick_sort_3way(nums, lo, lt)
    quick_sort_3way(nums, gt, hi)

