#include <random>

// 手写快速排序（随机基准 + 挖坑划分）：平均 O(n log n)，随机化避免有序数据退化
class Solution {
    mt19937 rng{random_device{}()};

    void quick_sort(vector<int>& nums, int lo, int hi) {
        if (lo >= hi) return;                                 // 区间长度 <= 1 直接返回
        int p = uniform_int_distribution<int>(lo, hi)(rng);   // 随机选基准下标
        swap(nums[lo], nums[p]);                              // 基准移到头部，防有序输入退化
        int val = nums[lo], i = lo, j = hi;                   // 挖坑法：val 即基准值
        while (i < j) {
            while (i < j && nums[j] >= val) --j;              // j 从右往左找第一个 < val
            nums[i] = nums[j];                                // 填左坑
            while (i < j && nums[i] <= val) ++i;              // i 从左往右找第一个 > val
            nums[j] = nums[i];                                // 填右坑
        }
        nums[i] = val;                                        // 基准归位
        quick_sort(nums, lo, i - 1);                          // 分治左半段
        quick_sort(nums, i + 1, hi);                          // 分治右半段
    }

public:
    vector<int> sortArray(vector<int>& nums) {
        shuffle(nums.begin(), nums.end(), rng);   // 先打乱再排序，进一步防退化
        quick_sort(nums, 0, (int)nums.size() - 1);
        return nums;
    }
};

