// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（数组长度）
//   第二行：n 个整数
// 输出格式：一行 n 个整数，升序排列，空格分隔
#include <algorithm>
#include <iostream>
#include <random>
#include <vector>
using namespace std;

// 随机选基准的挖坑划分：把 <val 放左、>val 放右，返回基准归位下标
int partition_qs(vector<int>& nums, int lo, int hi, mt19937& rng) {
    int p = uniform_int_distribution<int>(lo, hi)(rng);   // 随机基准下标
    swap(nums[lo], nums[p]);                              // 基准移到头部
    int val = nums[lo], i = lo, j = hi;
    while (i < j) {
        while (i < j && nums[j] >= val) --j;              // j 从右往左找第一个 < val
        nums[i] = nums[j];                                // 填左坑
        while (i < j && nums[i] <= val) ++i;              // i 从左往右找第一个 > val
        nums[j] = nums[i];                                // 填右坑
    }
    nums[i] = val;                                        // 基准归位
    return i;
}

void quick_sort(vector<int>& nums, int lo, int hi, mt19937& rng) {
    if (lo >= hi) return;                                 // 区间长度 <= 1 直接返回
    int p = partition_qs(nums, lo, hi, rng);
    quick_sort(nums, lo, p - 1, rng);                     // 分治左半段
    quick_sort(nums, p + 1, hi, rng);                     // 分治右半段
}

int main() {
    ios::sync_with_stdio(false);                          // 关闭同步加速 IO
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> nums(n);
    for (int i = 0; i < n; ++i) cin >> nums[i];
    mt19937 rng{random_device{}()};
    shuffle(nums.begin(), nums.end(), rng);               // 先打乱再排序，进一步防退化
    quick_sort(nums, 0, n - 1, rng);
    for (int i = 0; i < n; ++i) {                         // 一行空格分隔输出
        if (i) cout << ' ';
        cout << nums[i];
    }
    cout << '\n';
    return 0;
}

