class Solution {
    // 手写快速排序：随机基准 + 挖坑划分，平均 O(n log n)
    public int[] sortArray(int[] nums) {
        Random rnd = new Random();
        quickSort(nums, 0, nums.length - 1, rnd);
        return nums;
    }

    private void quickSort(int[] nums, int lo, int hi, Random rnd) {
        if (lo >= hi) return;                          // 区间长度 <= 1 直接返回
        int p = lo + rnd.nextInt(hi - lo + 1);         // 随机选基准，防有序输入退化
        swap(nums, lo, p);                             // 基准移到头部
        int val = nums[lo], i = lo, j = hi;            // 挖坑法：val 即基准值
        while (i < j) {
            while (i < j && nums[j] >= val) j--;       // j 从右往左找第一个 < val
            nums[i] = nums[j];                         // 填左坑
            while (i < j && nums[i] <= val) i++;       // i 从左往右找第一个 > val
            nums[j] = nums[i];                         // 填右坑
        }
        nums[i] = val;                                 // 基准归位
        quickSort(nums, lo, i - 1, rnd);               // 分治左半段
        quickSort(nums, i + 1, hi, rnd);               // 分治右半段
    }

    private void swap(int[] nums, int a, int b) {
        int tmp = nums[a];
        nums[a] = nums[b];
        nums[b] = tmp;
    }
}

