/**
 * 手写快速排序（随机基准 + 挖坑划分），原地排序 nums[lo..hi] 区间
 * @param {number[]} nums 待排序数组（原地修改）
 * @param {number} lo 区间左端点（含）
 * @param {number} hi 区间右端点（含）
 * @return {void}
 */
function quickSort(nums, lo, hi) {
  if (lo >= hi) return;                                    // 区间长度 <= 1 直接返回
  const p = lo + Math.floor(Math.random() * (hi - lo + 1)); // 随机选基准下标
  [nums[lo], nums[p]] = [nums[p], nums[lo]];               // 基准移到头部防退化
  const val = nums[lo];
  let i = lo, j = hi;                                      // 挖坑法：val 即基准值
  while (i < j) {
    while (i < j && nums[j] >= val) j--;                   // j 从右往左找第一个 < val
    nums[i] = nums[j];                                     // 填左坑
    while (i < j && nums[i] <= val) i++;                   // i 从左往右找第一个 > val
    nums[j] = nums[i];                                     // 填右坑
  }
  nums[i] = val;                                           // 基准归位
  quickSort(nums, lo, i - 1);                              // 分治左半段
  quickSort(nums, i + 1, hi);                              // 分治右半段
}

