def merge_sort_bottom_up(nums):
    n = len(nums)
    width = 1
    while width < n:
        for lo in range(0, n, 2 * width):
            mid = min(lo + width, n)
            hi = min(lo + 2 * width, n)
            # 合并 [lo,mid) 与 [mid,hi)
            tmp = []
            i, j = lo, mid
            while i < mid and j < hi:
                if nums[i] <= nums[j]:
                    tmp.append(nums[i]); i += 1
                else:
                    tmp.append(nums[j]); j += 1
            tmp.extend(nums[i:mid]); tmp.extend(nums[j:hi])
            nums[lo:hi] = tmp
        width *= 2

