    if lo >= hi:
        return
    mid = (lo + hi) // 2
    merge_sort(nums, lo, mid)
    merge_sort(nums, mid + 1, hi)
    tmp = []
    i, j = lo, mid + 1
    while i <= mid and j <= hi:
        if nums[i] <= nums[j]:
            tmp.append(nums[i])
            i += 1
        else:
            tmp.append(nums[j])
            j += 1
    if i <= mid:
        tmp.extend(nums[i:mid + 1])
    if j <= hi:
        tmp.extend(nums[j:hi + 1])
    nums[lo:hi + 1] = tmp

