// 手写归并排序：递归二分 + 双指针合并两个有序段（稳定，O(n log n)）
class Solution {
    void merge_sort(vector<int>& nums, vector<int>& tmp, int lo, int hi) {
        if (lo >= hi) return;                          // 区间长度 <= 1 无需排序
        int mid = lo + (hi - lo) / 2;
        merge_sort(nums, tmp, lo, mid);                // 递归排左半段
        merge_sort(nums, tmp, mid + 1, hi);            // 递归排右半段
        int i = lo, j = mid + 1, k = lo;               // 双指针合并两个有序段
        while (i <= mid && j <= hi) {
            if (nums[i] <= nums[j])                    // 相等先取左段 → 稳定
                tmp[k++] = nums[i++];
            else
                tmp[k++] = nums[j++];
        }
        while (i <= mid) tmp[k++] = nums[i++];         // 左段剩余接上
        while (j <= hi) tmp[k++] = nums[j++];          // 右段剩余接上
        for (k = lo; k <= hi; ++k) nums[k] = tmp[k];   // 写回原数组
    }

public:
    vector<int> sortArray(vector<int>& nums) {
        vector<int> tmp(nums.size());                  // O(n) 辅助数组
        merge_sort(nums, tmp, 0, (int)nums.size() - 1);
        return nums;
    }
};

problems.acmCodeCpp:
// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（数组长度）
//   第二行：n 个整数
// 输出格式：一行 n 个整数，升序排列，空格分隔
#include <iostream>
#include <vector>
using namespace std;

// 合并两个有序段 [lo,mid] 与 [mid+1,hi] 到临时数组后写回
void merge_part(vector<int>& nums, vector<int>& tmp, int lo, int mid, int hi) {
    int i = lo, j = mid + 1, k = lo;                   // 双指针：i 扫左段，j 扫右段
    while (i <= mid && j <= hi) {
        if (nums[i] <= nums[j]) tmp[k++] = nums[i++];  // 相等先取左段 → 稳定
        else tmp[k++] = nums[j++];
    }
    while (i <= mid) tmp[k++] = nums[i++];             // 左段剩余接上
    while (j <= hi) tmp[k++] = nums[j++];              // 右段剩余接上
    for (k = lo; k <= hi; ++k) nums[k] = tmp[k];       // 写回原数组
}

void merge_sort(vector<int>& nums, vector<int>& tmp, int lo, int hi) {
    if (lo >= hi) return;                              // 区间长度 <= 1 无需排序
    int mid = lo + (hi - lo) / 2;
    merge_sort(nums, tmp, lo, mid);                    // 递归排左半段
    merge_sort(nums, tmp, mid + 1, hi);                // 递归排右半段
    merge_part(nums, tmp, lo, mid, hi);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> nums(n);
    for (int i = 0; i < n; ++i) cin >> nums[i];
    vector<int> tmp(n);                                // O(n) 辅助数组
    merge_sort(nums, tmp, 0, n - 1);
    for (int i = 0; i < n; ++i) {
        if (i) cout << ' ';
        cout << nums[i];
    }
    cout << '\n';
    return 0;
}

