problems.codeJs:
/**
 * 手写归并排序（自顶向下）：递归二分 + 双指针合并，稳定 O(n log n)
 * @param {number[]} nums 待排序数组（原地修改）
 * @param {number} lo 区间左端点（含）
 * @param {number} hi 区间右端点（含）
 * @return {void}
 */
function mergeSort(nums, lo, hi) {
  if (lo >= hi) return;                              // 区间长度 <= 1 无需排序
  const mid = (lo + hi) >> 1;
  mergeSort(nums, lo, mid);                          // 递归排左半段
  mergeSort(nums, mid + 1, hi);                      // 递归排右半段
  const tmp = [];                                    // 合并缓冲区
  let i = lo, j = mid + 1;
  while (i <= mid && j <= hi) {
    tmp.push(nums[i] <= nums[j] ? nums[i++] : nums[j++]); // 相等先取左段 → 稳定
  }
  while (i <= mid) tmp.push(nums[i++]);              // 左段剩余接上
  while (j <= hi) tmp.push(nums[j++]);               // 右段剩余接上
  for (let k = 0; k < tmp.length; k++) nums[lo + k] = tmp[k]; // 写回原数组
}

