func mergeSort(nums []int, lo, hi int) {
	if lo >= hi {
		return // 区间长度 <= 1 无需排序
	}
	mid := lo + (hi-lo)/2
	mergeSort(nums, lo, mid)       // 递归排左半段
	mergeSort(nums, mid+1, hi)     // 递归排右半段
	tmp := make([]int, 0, hi-lo+1) // 合并缓冲区
	i, j := lo, mid+1
	for i <= mid && j <= hi {
		if nums[i] <= nums[j] { // 相等先取左段 → 稳定
			tmp = append(tmp, nums[i])
			i++
		} else {
			tmp = append(tmp, nums[j])
			j++
		}
	}
	for i <= mid { // 左段剩余接上
		tmp = append(tmp, nums[i])
		i++
	}
	for j <= hi { // 右段剩余接上
		tmp = append(tmp, nums[j])
		j++
	}
	for k, v := range tmp { // 写回原数组
		nums[lo+k] = v
	}
}

