# ACM 模式完整程序
# 输入：第一行 n；接下来 n 行，"1 x" 表示插入 x，"2" 表示弹出堆顶并输出
# 输出：每个弹出操作输出一行
import sys

class MinHeap:
    def __init__(self):
        self.a = []

    def push(self, x):
        self.a.append(x)
        i = len(self.a) - 1
        while i > 0:
            p = (i - 1) // 2
            if self.a[i] < self.a[p]:
                self.a[i], self.a[p] = self.a[p], self.a[i]
                i = p
            else:
                break

    def pop(self):
        top = self.a[0]
        last = self.a.pop()
        if self.a:
            self.a[0] = last
            self._down(0)
        return top

    def _down(self, i):
        n = len(self.a)
        while True:
            l, r = 2 * i + 1, 2 * i + 2
            m = i
            if l < n and self.a[l] < self.a[m]:
                m = l
            if r < n and self.a[r] < self.a[m]:
                m = r
            if m == i:
                break
            self.a[i], self.a[m] = self.a[m], self.a[i]
            i = m

def main():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    heap = MinHeap()
    out = []
    for _ in range(n):
        op = data[idx]; idx += 1
        if op == '1':
            heap.push(int(data[idx])); idx += 1
        else:
            out.append(str(heap.pop()))
    print('\n'.join(out))

if __name__ == '__main__':
    main()

