// 数组实现的小顶堆：下标 i 的父为 (i-1)/2、孩子为 2i+1/2i+2；push/pop 均 O(log n)
class MinHeap {
    vector<int> a;                       // 数组存完全二叉树

    void down(int i) {                   // 下沉：与较小的孩子交换
        int n = (int)a.size();
        while (true) {
            int l = 2 * i + 1, r = 2 * i + 2, m = i;
            if (l < n && a[l] < a[m]) m = l;      // 选较小的孩子
            if (r < n && a[r] < a[m]) m = r;
            if (m == i) break;                    // 已满足堆序
            swap(a[i], a[m]);
            i = m;
        }
    }

public:
    void push(int x) {
        a.push_back(x);                  // 尾插后上浮
        int i = (int)a.size() - 1;
        while (i > 0) {
            int p = (i - 1) / 2;         // 父节点下标
            if (a[i] < a[p]) {           // 比父小则交换
                swap(a[i], a[p]);
                i = p;
            } else break;
        }
    }

    int pop() {
        int top = a[0];                  // 堆顶即最小值
        int last = a.back();
        a.pop_back();
        if (!a.empty()) {                // 尾补头后下沉
            a[0] = last;
            down(0);
        }
        return top;
    }
};

