//   接下来 n 行：每行 "1 x" 表示把 x 入堆，"2" 表示弹出堆顶并输出
// 输出格式：每个 "2" 操作输出一行弹出的值
#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

class MinHeap {
    vector<int> a;                       // 数组存完全二叉树

    void down(int i) {                   // 下沉：与较小的孩子交换
        int n = (int)a.size();
        while (true) {
            int l = 2 * i + 1, r = 2 * i + 2, m = i;
            if (l < n && a[l] < a[m]) m = l;      // 选较小的孩子
            if (r < n && a[r] < a[m]) m = r;
            if (m == i) break;                    // 已满足堆序
            swap(a[i], a[m]);
            i = m;
        }
    }

public:
    void push(int x) {                   // 尾插后上浮
        a.push_back(x);
        int i = (int)a.size() - 1;
        while (i > 0) {
            int p = (i - 1) / 2;         // 父节点下标
            if (a[i] < a[p]) {           // 比父小则交换
                swap(a[i], a[p]);
                i = p;
            } else break;
        }
    }

    int pop() {                          // 弹出堆顶：尾补头后下沉
        int top = a[0];
        int last = a.back();
        a.pop_back();
        if (!a.empty()) { a[0] = last; down(0); }
        return top;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    MinHeap heap;
    for (int k = 0; k < n; ++k) {
        string op;
        cin >> op;
        if (op == "1") {                 // 插入操作
            int x;
            cin >> x;
            heap.push(x);
        } else {                         // 弹出操作
            cout << heap.pop() << '\n';
        }
    }
    return 0;
}

