/**
 * 数组实现的小顶堆：下标 i 的父为 (i-1)/2，孩子为 2i+1、2i+2
 * push 尾插后上浮，pop 尾补头后下沉，均 O(log n)
 */
class MinHeap {
  constructor() {
    this.a = [];                        // 数组存完全二叉树
  }

  /** 插入元素：尾插后与父节点比较上浮
   * @param {number} x
   */
  push(x) {
    this.a.push(x);
    let i = this.a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;           // 父节点下标
      if (this.a[i] < this.a[p]) {      // 比父小则交换
        [this.a[i], this.a[p]] = [this.a[p], this.a[i]];
        i = p;
      } else break;
    }
  }

  /** 弹出最小值：堆顶出、尾补头后下沉
   * @return {number}
   */
  pop() {
    const top = this.a[0];              // 堆顶即最小值
    const last = this.a.pop();
    if (this.a.length > 0) {
      this.a[0] = last;
      this.down(0);
    }
    return top;
  }

  /** 下沉：与较小的孩子交换，维护堆序 */
  down(i) {
    const n = this.a.length;
    while (true) {
      const l = 2 * i + 1, r = 2 * i + 2;
      let m = i;
      if (l < n && this.a[l] < this.a[m]) m = l;  // 选较小的孩子
      if (r < n && this.a[r] < this.a[m]) m = r;
      if (m === i) break;
      [this.a[i], this.a[m]] = [this.a[m], this.a[i]];
      i = m;
    }
  }
}

