// MinHeap 数组实现的小顶堆：下标 i 的父为 (i-1)/2，孩子为 2i+1、2i+2
type MinHeap struct {
	a []int // 数组存完全二叉树
}

// Push 插入元素：尾插后与父节点比较上浮
func (h *MinHeap) Push(x int) {
	h.a = append(h.a, x)
	i := len(h.a) - 1
	for i > 0 {
		p := (i - 1) / 2 // 父节点下标
		if h.a[i] < h.a[p] { // 比父小则交换
			h.a[i], h.a[p] = h.a[p], h.a[i]
			i = p
		} else {
			break
		}
	}
}

// Pop 弹出最小值：堆顶出、尾补头后下沉
func (h *MinHeap) Pop() int {
	top := h.a[0] // 堆顶即最小值
	last := h.a[len(h.a)-1]
	h.a = h.a[:len(h.a)-1]
	if len(h.a) > 0 {
		h.a[0] = last
		h.down(0)
	}
	return top
}

// down 下沉：与较小的孩子交换，维护堆序
func (h *MinHeap) down(i int) {
	n := len(h.a)
	for {
		l, r, m := 2*i+1, 2*i+2, i
		if l < n && h.a[l] < h.a[m] { // 选较小的孩子
			m = l
		}
		if r < n && h.a[r] < h.a[m] {
			m = r
		}
		if m == i {
			break
		}
		h.a[i], h.a[m] = h.a[m], h.a[i]
		i = m
	}
}

