// 大数加法：双指针从两串末尾逐位相加 + 进位（模拟竖式），最后反转
class Solution {
public:
    string addStrings(string a, string b) {
        int i = (int)a.size() - 1, j = (int)b.size() - 1;
        int carry = 0;
        string res;
        while (i >= 0 || j >= 0 || carry) {
            int da = i >= 0 ? a[i] - '0' : 0;   // 短的一侧补 0
            int db = j >= 0 ? b[j] - '0' : 0;
            int s = da + db + carry;
            res.push_back(char('0' + s % 10));  // 当前位（低位在前）
            carry = s / 10;                     // 进位传给下一位
            --i; --j;
        }
        reverse(res.begin(), res.end());        // 反转为正常高位在前
        return res;
    }
};

