    const da = i >= 0 ? a.charCodeAt(i) - 48 : 0; // 短的一侧补 0
    const db = j >= 0 ? b.charCodeAt(j) - 48 : 0;
    const s = da + db + carry;
    res.push(s % 10);                             // 当前位（低位在前）
    carry = Math.floor(s / 10);                   // 进位传给下一位
    i--; j--;
  }
