func bigAdd(a, b string) string {
	i, j := len(a)-1, len(b)-1
	carry := 0
	res := []byte{}
	for i >= 0 || j >= 0 || carry > 0 {
		da, db := 0, 0
		if i >= 0 { // 短的一侧补 0
			da = int(a[i] - '0')
		}
		if j >= 0 {
			db = int(b[j] - '0')
		}
		s := da + db + carry
		res = append(res, byte('0'+s%10)) // 当前位（低位在前）
		carry = s / 10                    // 进位传给下一位
		i--
		j--
	}
	for l, r := 0, len(res)-1; l < r; l, r = l+1, r-1 { // 反转成正常顺序
		res[l], res[r] = res[r], res[l]
	}
	return string(res)
}

