// 栈匹配括号：左括号入栈，右括号弹栈配对；栈空才返回 true（左括号多余也判失败）
class Solution {
public:
    bool isValid(string s) {
        unordered_map<char, char> pair{{')', '('}, {']', '['}, {'}', '{'}};
        stack<char> st;
        for (char c : s) {
            if (c == '(' || c == '[' || c == '{') {
                st.push(c);                    // 左括号入栈
            } else {
                if (st.empty() || st.top() != pair[c])
                    return false;              // 右括号时栈空或栈顶不配对
                st.pop();
            }
        }
        return st.empty();                     // 结束后栈非空说明左括号多余
    }
};

