def lower_bound(nums, x):
    left, right = 0, len(nums)      # [0,left)<x, [right,n)>=x
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < x:
            left = mid + 1          # mid 不可能是答案
        else:
            right = mid             # mid 可能是答案，保留
    return left                     # 第一个 >=x 的位置

