def find_first_recursive(nums, x, lo=0, hi=None):
    if hi is None:
        hi = len(nums) - 1
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if nums[mid] == x:
        # 命中也可能不是第一次出现，向左再找更小的下标
        left_ans = find_first_recursive(nums, x, lo, mid - 1)
        return left_ans if left_ans != -1 else mid
    if nums[mid] < x:
        return find_first_recursive(nums, x, mid + 1, hi)
    return find_first_recursive(nums, x, lo, mid - 1)

