// lower_bound：返回第一个 >= x 的下标；区间不变式 [0,left)<x、[right,n)>=x 收敛
int lower_bound_idx(const vector<int>& nums, int x) {
    int left = 0, right = (int)nums.size();
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] < x)
            left = mid + 1;                     // mid 不可能是答案
        else
            right = mid;                        // mid 可能是答案，保留
    }
    return left;                                // 第一个 >= x 的位置
}

