    int left = 0, right = (int)nums.size();
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] < x) left = mid + 1;     // mid 不可能是答案
        else right = mid;                      // mid 可能是答案，保留
    }
