/**
 * 左边界二分：返回第一个 >= x 的下标
 * 区间不变式：[0, left) 全部 < x，[right, n) 全部 >= x
 * @param {number[]} nums 升序数组
 * @param {number} x
 * @return {number} 第一个 >= x 的下标
 */
function lowerBound(nums, x) {
  let left = 0, right = nums.length;
  while (left < right) {
    const mid = (left + right) >> 1;
    if (nums[mid] < x) left = mid + 1; // mid 不可能是答案
    else right = mid;                  // mid 可能是答案，保留
  }
  return left;                         // 第一个 >= x 的位置
}

/** 找 x 首次出现的下标（0 起），不存在返回 -1
 * @param {number[]} nums
 * @param {number} x
 * @return {number}
 */
function findFirst(nums, x) {
  const p = lowerBound(nums, x);
  return p < nums.length && nums[p] === x ? p : -1;
}

