// 区间不变式：[0, left) 全部 < x，[right, n) 全部 >= x
func lowerBound(nums []int, x int) int {
	left, right := 0, len(nums)
	for left < right {
		mid := left + (right-left)/2
		if nums[mid] < x {
			left = mid + 1 // mid 不可能是答案
		} else {
			right = mid // mid 可能是答案，保留
		}
	}
	return left // 第一个 >= x 的位置
}

// findFirst 找 x 首次出现的下标（0 起），不存在返回 -1
func findFirst(nums []int, x int) int {
	p := lowerBound(nums, x)
	if p < len(nums) && nums[p] == x {
		return p
	}
	return -1
}

