// 无权网格最短路：BFS 层数即步数；visited 在入队时标记，防止重复入队
int shortest_path(const vector<vector<int>>& g) {
    int n = (int)g.size(), m = (int)g[0].size();
    if (g[0][0] == 1 || g[n - 1][m - 1] == 1) return -1;   // 起/终点是墙
    vector<vector<bool>> visited(n, vector<bool>(m, false));
    queue<tuple<int, int, int>> q;                         // (x, y, dist)
    q.push({0, 0, 0});
    visited[0][0] = true;
    int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};   // 四方向
    while (!q.empty()) {
        auto [x, y, d] = q.front();
        q.pop();
        if (x == n - 1 && y == m - 1) return d;            // 首次到终点即最短
        for (auto& dr : dirs) {
            int nx = x + dr[0], ny = y + dr[1];
            if (0 <= nx && nx < n && 0 <= ny && ny < m &&
                g[nx][ny] == 0 && !visited[nx][ny]) {
                visited[nx][ny] = true;                    // 入队时标记！
                q.push({nx, ny, d + 1});
            }
        }
    }
    return -1;                                             // 队空未达终点
}

