	visited[0][0] = true
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} // 四方向
	for len(q) > 0 {
		c := q[0]
		q = q[1:]
		if c.x == n-1 && c.y == m-1 {
			return c.d // 首次到终点即最短
		}
		for _, dr := range dirs {
			nx, ny := c.x+dr[0], c.y+dr[1]
			if 0 <= nx && nx < n && 0 <= ny && ny < m &&
				g[nx][ny] == 0 && !visited[nx][ny] {
				visited[nx][ny] = true // 入队时标记！
				q = append(q, cell{nx, ny, c.d + 1})
			}
		}
	}
	return -1 // 走不到终点
}

