// 迭代版 find：第一趟找根，第二趟把沿途节点直接挂到根上（路径压缩）
int find_dsu(vector<int>& fa, int x) {
    int root = x;
    while (fa[root] != root) root = fa[root];   // 第一趟：沿父链找根
    while (fa[x] != root) {                     // 第二趟：路径压缩
        int nxt = fa[x];
        fa[x] = root;
        x = nxt;
    }
    return root;
}

// union：两根不同才合并，连通块数减一
void union_dsu(vector<int>& fa, int& cnt, int a, int b) {
    int ra = find_dsu(fa, a), rb = find_dsu(fa, b);
    if (ra != rb) {                             // 根不同才算新合并
        fa[ra] = rb;
        --cnt;
    }
}

