    public int countComponents(int n, int[][] edges) {
        int[] fa = new int[n + 1];
        for (int i = 1; i <= n; i++) fa[i] = i;    // 初始指向自己
        int cnt = n;
        for (int[] e : edges) {
            int ra = find(fa, e[0]), rb = find(fa, e[1]);
            if (ra != rb) {                        // 根不同才算新合并
                fa[ra] = rb;
                cnt--;
            }
        }
        return cnt;                                // 连通块个数
    }
