/**
 * 迭代版 find：第一趟找根，第二趟把沿途节点直接挂到根上（路径压缩）
 * @param {number[]} fa 父节点数组
 * @param {number} x
 * @return {number} 根节点编号
 */
function find(fa, x) {
  let root = x;
  while (fa[root] !== root) root = fa[root];  // 第一趟：沿父链找根
  while (fa[x] !== root) {                    // 第二趟：路径压缩
    const nxt = fa[x];
    fa[x] = root;
    x = nxt;
  }
  return root;
}

/** 并查集连通块计数：初始每节点一块，成功合并一次块数减一
 * @param {number} n 节点数（1..n）
 * @param {number[][]} edges 每条边 [a, b] 表示合并
 * @return {number} 连通块个数
 */
function countComponents(n, edges) {
  const fa = Array.from({ length: n + 1 }, (_, i) => i); // 初始指向自己
  let cnt = n;
  for (const [a, b] of edges) {
    const ra = find(fa, a), rb = find(fa, b);
    if (ra !== rb) {                           // 根不同才算新合并
      fa[ra] = rb;
      cnt--;
    }
  }
  return cnt;                                  // 连通块个数
}

