        color[u] = 1                  # 进入：标灰
        for v in adj[u]:
            if color[v] == 1:
                return False          # 灰色重遇 → 有环
            if color[v] == 0 and not dfs(v):
                return False
        color[u] = 2                  # 完成：标黑
