// Kahn 拓扑排序：入度表 + 小顶堆，每次取编号最小的可执行节点（字典序最小）
vector<int> topo(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> adj(n + 1);
    vector<int> indeg(n + 1, 0);
    for (auto& e : edges) {
        adj[e.first].push_back(e.second);       // 依赖边 a -> b
        indeg[e.second]++;                      // b 入度 +1
    }
    priority_queue<int, vector<int>, greater<int>> heap;   // 小顶堆
    for (int v = 1; v <= n; ++v)
        if (indeg[v] == 0) heap.push(v);        // 初始可执行节点
    vector<int> order;
    while (!heap.empty()) {
        int u = heap.top(); heap.pop();         // 取字典序最小的可执行节点
        order.push_back(u);
        for (int v : adj[u]) {
            if (--indeg[v] == 0) heap.push(v);  // 入度归零入堆
        }
    }
    return (int)order.size() == n ? order : vector<int>();   // 空 = 有环
}

