        int k = 0;
        while (!heap.isEmpty()) {
            int u = heap.poll();                 // 取字典序最小的可执行节点
            order[k++] = u;
            for (int v : adj.get(u)) {
                if (--indeg[v] == 0) heap.offer(v);  // 入度归零入堆
            }
        }
        return k == n ? order : new int[0];      // 空数组 = 有环
    }
