/**
 * Kahn 拓扑排序：入度表 + 小顶堆，每次取编号最小的可执行节点（字典序最小）
 * @param {number} n 任务数（1..n）
 * @param {number[][]} edges 依赖边 [a, b] 表示 a 必须在 b 之前完成
 * @return {number[]} 字典序最小的拓扑序；有环返回空数组
 */
function topo(n, edges) {
  const adj = Array.from({ length: n + 1 }, () => []);
  const indeg = new Array(n + 1).fill(0);
  for (const [a, b] of edges) {
    adj[a].push(b);                       // 依赖边 a -> b
    indeg[b]++;                           // b 入度 +1
  }
  const heap = [];                        // 小顶堆：存当前可执行节点
  const pushHeap = (x) => {               // 堆插入：尾插后上浮
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;             // 父节点下标
      if (heap[i] < heap[p]) {
        [heap[i], heap[p]] = [heap[p], heap[i]];
        i = p;
      } else break;
    }
  };
  const popHeap = () => {                 // 堆弹出：头出尾补后下沉
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = 2 * i + 2;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;   // 选较小的孩子
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };
  for (let v = 1; v <= n; v++) if (indeg[v] === 0) pushHeap(v);  // 初始可执行节点
  const order = [];
  while (heap.length) {
    const u = popHeap();                  // 取字典序最小的可执行节点
    order.push(u);
    for (const v of adj[u]) {
      if (--indeg[v] === 0) pushHeap(v);  // 入度归零入堆
    }
  }
  return order.length === n ? order : []; // 长度不足 n = 有环
}

problems.codeGo:
// topo Kahn 拓扑排序：入度表 + 小顶堆，每次取编号最小的可执行节点（字典序最小）
func topo(n int, edges [][2]int) []int {
	adj := make([][]int, n+1)
	indeg := make([]int, n+1)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], e[1]) // 依赖边 a -> b
		indeg[e[1]]++                       // b 入度 +1
	}
	heap := []int{}
	push := func(x int) { // 堆插入：尾插后上浮
		heap = append(heap, x)
		i := len(heap) - 1
		for i > 0 {
			p := (i - 1) / 2 // 父节点下标
			if heap[i] >= heap[p] {
				break
			}
			heap[i], heap[p] = heap[p], heap[i]
			i = p
		}
	}
	pop := func() int { // 堆弹出：头出尾补后下沉
		top := heap[0]
		heap[0] = heap[len(heap)-1]
		heap = heap[:len(heap)-1]
		i, sz := 0, len(heap)
		for {
			l, r, m := 2*i+1, 2*i+2, i
			if l < sz && heap[l] < heap[m] { // 选较小的孩子
				m = l
			}
			if r < sz && heap[r] < heap[m] {
				m = r
			}
			if m == i {
				break
			}
			heap[i], heap[m] = heap[m], heap[i]
			i = m
		}
		return top
	}
	for v := 1; v <= n; v++ {
		if indeg[v] == 0 {
			push(v) // 初始可执行节点
		}
	}
	order := []int{}
	for len(heap) > 0 {
		u := pop() // 取字典序最小的可执行节点
		order = append(order, u)
		for _, v := range adj[u] {
			indeg[v]--
			if indeg[v] == 0 {
				push(v) // 入度归零入堆
			}
		}
	}
	if len(order) < n {
		return []int{} // 长度不足 n = 有环
	}
	return order
}

