class Solution {
    // LIS 贪心 + 二分：tails[i] 为长度 i+1 的递增子序列的最小结尾，恒有序可二分
    public int lengthOfLIS(int[] nums) {
        List<Integer> tails = new ArrayList<>();  // tails 保持严格递增
        for (int x : nums) {
            // 手写 lower_bound：第一个 >= x 的位置
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (tails.get(mid) < x) lo = mid + 1;
                else hi = mid;
            }
            if (lo == tails.size()) tails.add(x);  // x 延伸出更长子序列
            else tails.set(lo, x);                 // 换成更小结尾，给后续留余地
        }
        return tails.size();                       // tails 长度即 LIS 长度
    }
}

