 * @param {number[]} nums
 * @return {number} 最长严格递增子序列的长度
 */
function lengthOfLIS(nums) {
  const tails = [];                              // tails 保持严格递增
  for (const x of nums) {
    // 手写 lower_bound：第一个 >= x 的位置
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1;          // mid 不可能是替换位置
      else hi = mid;
    }
    if (lo === tails.length) tails.push(x);      // x 延伸出更长子序列
    else tails[lo] = x;                          // 换成更小结尾，给后续留余地
  }
  return tails.length;                           // tails 长度即 LIS 长度
}

