// 区间合并：按左端点排序后一次扫描，相交（含端点相接）则右端点取 max
vector<vector<int>> merge_intervals(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end());   // 按左端点升序
    vector<vector<int>> res;
    for (auto& iv : intervals) {
        if (res.empty() || iv[0] > res.back()[1]) {
            res.push_back(iv);                  // 不相交：开启新区间
        } else {
            res.back()[1] = max(res.back()[1], iv[1]);  // 合并，右端点取 max
        }
    }
    return res;
}

