class Solution {
    // 区间合并：按左端点排序后一次扫描，相交（含端点相接）则右端点取 max
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));  // 按左端点升序
        List<int[]> res = new ArrayList<>();
        for (int[] iv : intervals) {
            if (res.isEmpty() || iv[0] > res.get(res.size() - 1)[1]) {
                res.add(iv);                     // 不相交：开启新区间
            } else {
                int[] last = res.get(res.size() - 1);
                last[1] = Math.max(last[1], iv[1]);  // 合并，右端点取 max
            }
        }
        return res.toArray(new int[0][]);        // 转为二维数组返回
    }
}

