/**
 * 区间合并：按左端点排序后一次扫描，相交（含端点相接）则右端点取 max
 * @param {number[][]} intervals 每个区间 [l, r]
 * @return {number[][]} 合并后的区间列表（按左端点升序）
 */
function mergeIntervals(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);         // 按左端点升序
  const res = [];
  for (const [l, r] of intervals) {
    if (res.length === 0 || l > res[res.length - 1][1]) {
      res.push([l, r]);                          // 不相交：开启新区间
    } else {
      const last = res[res.length - 1];
      last[1] = Math.max(last[1], r);            // 合并，右端点取 max
    }
  }
  return res;
}

